  test("unrelated_partial_region_does_not_clear_unpresented_damage",[&]{auto root=data/"coverage";importBook(app,source,root);Harness h(app,root);h.stroke(250,700,650,800,6);h.settled();CHECK(h.shell.styledInk()->undo());until([&]{return h.shell.styledInk()->status().queued==0;});CHECK(h.shell.styledInk()->status().busy&&!h.shell.styledInk()->admissionOpen());CHECK(h.shell.styledInk()->tick());auto pending=h.shell.styledInk()->damage();CHECK(!pending.empty());h.shell.presentationCovered({0,0,1620,120});auto after=h.shell.styledInk()->damage();CHECK(after.x0==pending.x0&&after.y0==pending.y0&&after.x1==pending.x1&&after.y1==pending.y1);CHECK(h.display.submit(pending)==spike::Submit::Accepted&&h.shell.styledInk()->damage().empty());CHECK(h.shell.finish(5000));});
