  test("sleeping_pen_admission_is_closed_without_ending_clean_session",[&]{auto root=data/"sleep-admission";importBook(app,source,root);PowerFixture files(data/"fake-power-admission");auto now=spike::monotonic();recovery::v2::sessionpower::SessionPower power(files.root,"test-reader",5000000000ULL,files.root/"power",{},now,noSuspendOffset);CHECK(power.valid());Harness h(app,root,&power);h.settled();now=spike::monotonic();power.configure({false,1},now);CHECK(power.tick(now+2,true));CHECK(power.state()==recovery::v2::sessionpower::PowerState::SleepPending&&power.sleep(now+3));CHECK(h.shell.inkAdmission()&&h.shell.unsaved()==0);const bool admitted=h.display.admissionOpen();CHECK(!h.display.reserve());if(admitted)std::fprintf(stderr,"SLEEP_GATE_MISMATCH admission_open=true reserve=false unsaved=0\n");CHECK(!admitted);CHECK(h.display.readerBoundary()&&!h.shell.failed()&&h.shell.unsaved()==0);files.press();now=spike::monotonic();CHECK(power.tick(now,true)&&power.state()==recovery::v2::sessionpower::PowerState::Awake&&!power.endRequested(now));power.configure({false,0},now);CHECK(h.display.admissionOpen());h.stroke(600,900,650,920);h.settled();CHECK(h.shell.styledInk()->status().saved>0&&h.shell.unsaved()==0&&!h.shell.failed());CHECK(h.shell.finish(5000));std::puts("SLEEP_ADMISSION_PASS asleep_gate_closed=true clean_boundary_alive=true power_wake_write=true fake_power_only=true");});
