  test("overlapping_damage_plan_preserves_coverage_without_extra_area",[&]{for(unsigned seed=1;seed<=256;++seed){ux::RefreshPlan plan;std::array<spike::Rect,12> input{};std::uint64_t area=0;for(unsigned i=0;i<input.size();++i){unsigned a=seed*1103515245u+i*12345u;int x=int(a%48),y=int((a>>8)%48),w=1+int((a>>16)%16),height=1+int((a>>23)%16);input[i]={x,y,x+w,y+height};area+=ux::RefreshPlan::area(input[i]);CHECK(plan.add(input[i]));}std::uint64_t after=0;for(unsigned i=0;i<plan.count;++i)after+=ux::RefreshPlan::area(plan.regions[i]);CHECK(plan.count<=input.size()&&after<=area);for(int y=0;y<64;++y)for(int x=0;x<64;++x){bool required=false,covered=false;for(auto r:input)required|=r.contains(x,y);for(unsigned i=0;i<plan.count;++i)covered|=plan.regions[i].contains(x,y);CHECK(!required||covered);}}ux::RefreshPlan overflow;for(int i=0;i<16;++i)CHECK(overflow.add({i*40,100,i*40+10,110}));CHECK(!overflow.add({1000,100,1010,110})&&overflow.overflow&&overflow.count==16);});
  test("only_submitted_overlay_changes_receive_one_regional_quality_update",[&]{auto root=data/"ui-quality";importBook(app,source,root);Harness h(app,root);h.settled();CHECK(h.shell.action(ux::Action::Show));h.boundary();const auto initial=ux::DisplayTestAccess::cleanupSubmissions(h.display);CHECK(uitest::openTools(h.shell));CHECK(uitest::tap(h.shell,uitest::toolsClose(h.shell)));h.boundary();CHECK(ux::DisplayTestAccess::cleanupSubmissions(h.display)==initial);CHECK(uitest::openTools(h.shell));h.boundary();CHECK(ux::DisplayTestAccess::cleanupSubmissions(h.display)>initial);const auto shown=ux::DisplayTestAccess::cleanupSubmissions(h.display);for(unsigned n=0;n<25;++n)h.boundary();CHECK(ux::DisplayTestAccess::cleanupSubmissions(h.display)==shown);CHECK(uitest::tap(h.shell,uitest::toolsClose(h.shell)));h.boundary();CHECK(ux::DisplayTestAccess::cleanupSubmissions(h.display)>shown);const auto closed=ux::DisplayTestAccess::cleanupSubmissions(h.display);for(unsigned n=0;n<25;++n)h.boundary();CHECK(ux::DisplayTestAccess::cleanupSubmissions(h.display)==closed&&ux::DisplayTestAccess::pendingCleanup(h.display)==0);CHECK(h.shell.finish(5000));});
